// Posters and validation are generated by default; pass --video to also export MP4.
// node render.mjs /path/to/tmath-runtime [--audit] [clip-name]
import fs from 'node:fs/promises';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import {spawn} from 'node:child_process';
import {once} from 'node:events';
import sharp from 'sharp';
const dir=import.meta.dirname,bundle=path.resolve(process.argv[2]);
const auditOnly=process.argv.includes('--audit');
const filter=process.argv.slice(3).find(x=>!x.startsWith('--'))||'';
const manifest=JSON.parse(await fs.readFile(path.join(dir,'manifest.json'),'utf8'));
const out=path.resolve(dir,'../../IMAGE/07-SW-Fill/conic-series'),temp=path.join(dir,'temp');
await fs.mkdir(out,{recursive:true});await fs.mkdir(temp,{recursive:true});
const {createTMath}=await import(pathToFileURL(path.join(bundle,'client.js')));
const rt=await createTMath('return tmath.scene {width=960,height=1280}','boot.lua',{renderEngine:'cpu',wasmBinary:await fs.readFile(path.join(bundle,'tmath-wasm.wasm'))});
for(const [name,file] of [['Pretendard','Pretendard.ttf'],['Source Serif 4','SourceSerif4-Semibold.ttf'],['IBM Plex Sans KR','IBMPlexSansKR-SemiBold.ttf']])rt.font(name,await fs.readFile(path.join(bundle,file)),'ttf');
rt.hostTheme({dark:false,background:'#ffffff',foreground:'#333333',muted:'#717171',accent:'#006ab1',secondary:'#af00db',success:'#008000',warning:'#bf8803',danger:'#a1260d',info:'#007acc',surface:'#f3f3f3',line:'#d4d4d4',result:'#795e26',focus:'#111111',objects:['#006ab1','#af00db','#a31515','#098658']});
const summary=[];
function cropPixels(pixels,sw,crop){const [x,y,w,h]=crop;const input=Buffer.from(pixels),output=Buffer.alloc(w*h*4);for(let row=0;row<h;row++)input.copy(output,row*w*4,((y+row)*sw+x)*4,((y+row)*sw+x+w)*4);return output;}
try{
for(const spec of manifest.specs){
 if(!spec.clips.some(c=>c.name.includes(filter)))continue;
 rt.loadLua(await fs.readFile(path.join(dir,spec.name+'.lua'),'utf8'),spec.name+'.lua');
 const [sw]=rt.size();
 for(const clip of spec.clips.filter(c=>c.name.includes(filter))){
  const [cx,cy,width,height]=clip.crop,end=clip.end??rt.duration,duration=end+(clip.hold??0),frames=Math.ceil(duration*30)+1;
  const issues=new Set(),overlaps=new Set(),visibleIds=new Set();let clearance=Infinity;
  for(let frame=0;frame<frames;frame++){
   const time=Math.min(frame/30,end),report=rt.layoutReport(time,4);
   const texts=report.objects.filter(o=>o.type==='text'&&o.visible&&o.paintBounds?.width>0&&o.paintBounds?.height>0);
   const selected=[];
   for(const t of texts){const b=t.paintBounds;
    if(b.x+b.width<=cx||b.x>=cx+width||b.y+b.height<=cy||b.y>=cy+height)continue;
    visibleIds.add(t.id);selected.push(t);
    const inset=Math.min(b.x-cx,b.y-cy,cx+width-b.x-b.width,cy+height-b.y-b.height);clearance=Math.min(clearance,inset);
    if(inset<4)issues.add(`text crop ${t.id}: ${inset.toFixed(2)}`);
   }
   for(let i=0;i<selected.length;i++)for(let j=i+1;j<selected.length;j++){
    const a=selected[i],b=selected[j],ab=a.paintBounds,bb=b.paintBounds;
    const dx=Math.min(ab.x+ab.width,bb.x+bb.width)-Math.max(ab.x,bb.x),dy=Math.min(ab.y+ab.height,bb.y+bb.height)-Math.max(ab.y,bb.y);
    if(dx>1&&dy>1){
     // Original A/B labels intentionally crossfade in exactly the same location.
     if(a.id.replace(/state-[ab]-/,'state-')===b.id.replace(/state-[ab]-/,'state-'))continue;
     overlaps.add(`${a.id}/${b.id}`);
    }
   }
  }
  const audit={name:clip.name,source:spec.upstream,frames,duration,crop:clip.crop,minTextCanvasClearance:clearance,standaloneText:[...visibleIds],issues:[...issues],overlaps:[...overlaps]};
  summary.push(audit);console.log(JSON.stringify(audit));
  await fs.writeFile(path.join(temp,clip.name+'.audit.json'),JSON.stringify(audit,null,2));
  for(const [i,time] of [0,clip.poster,end].entries())await sharp(cropPixels(rt.render(time,true),sw,clip.crop),{raw:{width,height,channels:4}}).png().toFile(path.join(temp,`${clip.name}-${i}.png`));
  if(auditOnly)continue;
  if(issues.size||overlaps.size)throw Error('Review layout: '+clip.name);
  await sharp(cropPixels(rt.render(end,true),sw,clip.crop),{raw:{width,height,channels:4}}).webp({quality:92}).toFile(path.join(out,clip.name+'.webp'));
  if (!process.argv.includes('--video')) continue;
  const encoder=spawn('ffmpeg',['-hide_banner','-loglevel','error','-y','-f','rawvideo','-pix_fmt','rgba','-s',`${width}x${height}`,'-r','30','-i','pipe:0','-an','-c:v','libx264','-preset','medium','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',path.join(out,clip.name+'.mp4')],{stdio:['pipe','inherit','inherit']});
  const done=once(encoder,'close');
  for(let frame=0;frame<frames;frame++)if(!encoder.stdin.write(cropPixels(rt.render(Math.min(frame/30,end),true),sw,clip.crop)))await once(encoder.stdin,'drain');
  encoder.stdin.end();if((await done)[0])throw Error('ffmpeg failed');
  console.log('Exported '+clip.name);
 }
}
await fs.writeFile(path.join(temp,'summary.json'),JSON.stringify(summary,null,2));
}finally{rt.destroy();}
